CREATE TABLE "public"."service_order_parts" (
  "id"               bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "service_order_id" bigint                   NOT NULL,
  "qty"              integer                  NOT NULL DEFAULT 1,
  "part"             text                     NOT NULL,
  "description"      text,
  "location"         text,
  "updated_at"       timestamp with time zone NOT NULL DEFAULT now(),
  "part_due_date"    date,
  CONSTRAINT "service_order_parts_pkey" PRIMARY KEY (id),
  CONSTRAINT "service_order_parts_service_order_id_fkey" FOREIGN KEY (service_order_id) REFERENCES public.service_orders(service_order_id) ON DELETE CASCADE
);

ALTER TABLE "public"."service_order_parts"
  ENABLE ROW LEVEL SECURITY;

ALTER TABLE "public"."service_order_parts"
  ADD COLUMN "status" public.so_part_status DEFAULT 'pending'::public.so_part_status;

CREATE TRIGGER set_updated_at
  BEFORE UPDATE ON public.service_order_parts
  FOR EACH ROW
  EXECUTE FUNCTION public.handle_updated_at();

CREATE POLICY "Enable delete for admin and service" ON "public"."service_order_parts"
  FOR DELETE
  TO PUBLIC
  USING ((public.clerk_user_role() = ANY (ARRAY['admin'::text, 'service'::text, 'installation'::text])));

CREATE POLICY "Enable insert for service editors" ON "public"."service_order_parts"
  FOR INSERT
  TO PUBLIC
  WITH CHECK ((public.clerk_user_role() = ANY (ARRAY['admin'::text, 'installation'::text, 'service'::text])));

CREATE POLICY "Enable read access for authenticated users" ON "public"."service_order_parts"
  FOR SELECT
  TO PUBLIC
  USING ((auth.role() = 'authenticated'::text));

CREATE POLICY "Enable update for service editors" ON "public"."service_order_parts"
  FOR UPDATE
  TO PUBLIC
  USING ((public.clerk_user_role() = ANY (ARRAY['admin'::text, 'installation'::text, 'service'::text])));

REVOKE ALL ON SEQUENCE "public"."service_order_parts_id_seq" FROM "anon";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."service_order_parts_id_seq" TO "anon";

REVOKE ALL ON SEQUENCE "public"."service_order_parts_id_seq" FROM "authenticated";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."service_order_parts_id_seq" TO "authenticated";

REVOKE ALL ON SEQUENCE "public"."service_order_parts_id_seq" FROM "postgres";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."service_order_parts_id_seq" TO "postgres";

REVOKE ALL ON SEQUENCE "public"."service_order_parts_id_seq" FROM "service_role";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."service_order_parts_id_seq" TO "service_role";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."service_order_parts" TO "anon", "authenticated";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."service_order_parts" TO "service_role";

REVOKE ALL ON TABLE "public"."service_order_parts" FROM "postgres";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."service_order_parts" TO "postgres";
